export function getAvatarSource(url: string | null) {
  if (!url) return null;
  if (url.startsWith("local:")) {
    const key = url.replace("local:", "");
    return LOCAL_AVATAR_MAP[key] || require("../assets/avatars/default.png");
  }
  return { uri: url };
}

